CREATE OR REPLACE FUNCTION hermes.subir_documento(p_documento_id bigint, p_storage_path text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
begin
  if rol_actual() = '' and not contexto_confiable() then
    raise exception 'Requiere sesión autenticada';
  end if;

  update documento
     set estado = 'SUBIDO', storage_path = p_storage_path,
         subido_por = p_usuario, subido_en = now(),
         revisado_por = null, revisado_en = null, notas = null
   where id = p_documento_id
     and estado in ('PENDIENTE', 'RECHAZADO');

  if not found then
    raise exception 'Documento % no existe o no admite subida en su estado actual', p_documento_id;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.categoria_desde_tipo_precio(p_tipo_precio text)
 RETURNS hermes.categoria_cliente
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select (case lower(btrim(coalesce(p_tipo_precio, '')))
            when 'retail'      then 'RETAIL'
            when 'mayorista'   then 'MAYORISTA'
            when 'corporativo' then 'CORPORATIVO'
            when 'institucion' then 'INSTITUCIONAL'
            else null
          end)::categoria_cliente;
$function$
CREATE OR REPLACE FUNCTION public.app_rol_actual()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.rol
    from public.perfil p
   where p.id = auth.uid() and p.activo
   limit 1;
$function$
CREATE OR REPLACE FUNCTION hermes.siguiente_numero(p_tipo text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'hermes', 'public'
AS $function$
declare v_num bigint;
begin
  update contador_documento
     set ultimo_valor = ultimo_valor + 1
   where tipo = p_tipo
  returning ultimo_valor into v_num;

  if v_num is null then
    raise exception 'Tipo de documento desconocido: %', p_tipo;
  end if;
  return v_num;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.fn_autocompletar_partida_raiz()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if NEW.partida_raiz_id is null then
    NEW.partida_raiz_id := NEW.id;
  end if;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.consultar_saldos_por_pos_ids(p_pos_ids bigint[])
 RETURNS TABLE(pos_cliente_id bigint, hermes_cliente_id bigint, nombre text, saldo_confirmado numeric, monto_en_revision numeric, saldo_provisional numeric, situacion text, partidas_abiertas integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
  select c.pos_cliente_id, c.id, c.nombre,
         coalesce(vs.saldo_confirmado, 0),
         coalesce(vs.monto_en_revision, 0),
         coalesce(vs.saldo_provisional, 0),
         vs.situacion,
         (select count(*)::int from hermes.partida_abierta pa
           where pa.cliente_id = c.id and pa.estado = 'ABIERTA')
    from hermes.cliente c
    left join hermes.v_saldo_cliente vs on vs.cliente_id = c.id
   where c.pos_cliente_id = any(p_pos_ids);
$function$
CREATE OR REPLACE FUNCTION hermes.contexto_confiable()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Rama 1: conexión directa a Postgres (editor SQL, psql, pg_cron, MCP).
  --         El `auth.jwt() is null` la hace inalcanzable desde PostgREST.
  -- Rama 2: llamada con la service_role key (endpoints serverless).
  select (session_user = 'postgres' and auth.jwt() is null)
      or coalesce(auth.jwt() ->> 'role', '') = 'service_role';
$function$
CREATE OR REPLACE FUNCTION hermes.consultar_saldo(p_cliente_id bigint)
 RETURNS TABLE(saldo_confirmado numeric, saldo_provisional numeric, situacion text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare v_cliente_interno bigint;
begin
  select id into v_cliente_interno from cliente where pos_cliente_id = p_cliente_id;
  if v_cliente_interno is null then return; end if;
  return query
    select vs.saldo_confirmado, vs.saldo_provisional, vs.situacion
    from v_saldo_cliente vs where vs.cliente_id = v_cliente_interno;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.descartar_ingesta(p_ingesta_id bigint, p_motivo text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
begin
  if rol_actual() = '' and not contexto_confiable() then
    raise exception 'Requiere sesión autenticada';
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'El motivo es obligatorio';
  end if;

  update bandeja_ingesta
     set estado = 'DESCARTADO', notas = btrim(p_motivo),
         resuelto_por = p_usuario, resuelto_en = now()
   where id = p_ingesta_id and estado = 'PENDIENTE';

  if not found then
    raise exception 'La ingesta % no existe o ya fue resuelta', p_ingesta_id;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.fn_generar_expediente()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare v_hp record; v_h_id bigint;
begin
  for v_hp in
    select * from hito_plantilla
     where categoria = NEW.cliente_categoria
       and (NEW.parent_partida_id is null or fase = 'ENTREGA')
     order by orden
  loop
    insert into hito (partida_abierta_id, hito_plantilla_id, orden, nombre, obligatorio)
      values (NEW.id, v_hp.id, v_hp.orden, v_hp.nombre, v_hp.obligatorio)
      returning id into v_h_id;
    insert into documento (hito_id, documento_plantilla_id, etiqueta, tipo)
      select v_h_id, dp.id, dp.etiqueta, dp.tipo
        from documento_plantilla dp where dp.hito_plantilla_id = v_hp.id;
  end loop;
  return NEW;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.evaluar_credito_pos(p_pos_cliente_id bigint, p_monto numeric)
 RETURNS TABLE(permitido boolean, saldo_confirmado numeric, saldo_provisional numeric, limite_credito numeric, vencidos_documentados numeric, vencidos_sin_documentar numeric, sin_fecha_de_inicio numeric, contado_sin_cobrar numeric, entregados_sin_facturar integer, cheques_en_cartera numeric, motivo_advertencia text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare v_cliente_id bigint;
begin
  select c.id into v_cliente_id from cliente c where c.pos_cliente_id = p_pos_cliente_id;
  if v_cliente_id is null then
    raise exception 'El cliente % del POS no tiene cuenta en Hermes', p_pos_cliente_id;
  end if;
  return query select * from evaluar_credito(v_cliente_id, p_monto);
end;
$function$
CREATE OR REPLACE FUNCTION hermes.aplicar_extraccion_partida(p_documento_id bigint, p_usuario text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_partida bigint;
  v_ex      jsonb;
begin
  select h.partida_abierta_id, d.extraccion
    into v_partida, v_ex
    from documento d
    join hito h on h.id = d.hito_id
   where d.id = p_documento_id;
  if not found then raise exception 'El documento % no existe', p_documento_id; end if;
  if v_ex is null then raise exception 'El documento % no tiene extracción', p_documento_id; end if;

  perform registrar_fechas_partida(
    v_partida,
    nullif(v_ex ->> 'fecha_entrega', '')::date,
    nullif(v_ex ->> 'fecha_factura', '')::date,
    nullif(v_ex ->> 'cuf', ''),
    p_usuario
  );

  return v_partida;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.resolver_ingesta(p_ingesta_id bigint, p_documento_id bigint, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_ing record;
begin
  if rol_actual() = '' and not contexto_confiable() then
    raise exception 'Requiere sesión autenticada';
  end if;

  select * into v_ing from bandeja_ingesta where id = p_ingesta_id for update;
  if not found then raise exception 'La ingesta % no existe', p_ingesta_id; end if;
  if v_ing.estado <> 'PENDIENTE' then
    raise exception 'La ingesta % ya está %', p_ingesta_id, v_ing.estado;
  end if;

  -- El archivo ya está en storage; acá solo se le asigna dueño.
  perform ingesta_dirigida(p_documento_id, v_ing.storage_path, v_ing.agente,
                           v_ing.extraccion, v_ing.confianza);

  update bandeja_ingesta
     set estado = 'RESUELTO', documento_id = p_documento_id,
         resuelto_por = p_usuario, resuelto_en = now()
   where id = p_ingesta_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.consultar_saldos(p_cliente_ids bigint[])
 RETURNS TABLE(pos_cliente_id bigint, saldo_confirmado numeric, saldo_provisional numeric, limite_credito numeric, situacion text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
begin
  if p_cliente_ids is null or array_length(p_cliente_ids, 1) is null then
    return;
  end if;

  -- Tope defensivo: esto lo llama un endpoint serverless con service_role,
  -- así que el tamaño del array lo decide el cliente. 500 cubre de sobra el
  -- padrón real (25 hoy) y evita que un request armado a mano barra la tabla.
  if array_length(p_cliente_ids, 1) > 500 then
    raise exception 'Demasiados clientes en una sola consulta (máximo 500)';
  end if;

  return query
    select c.pos_cliente_id,
           vs.saldo_confirmado,
           vs.saldo_provisional,
           vs.limite_credito,
           vs.situacion
      from cliente c
      join v_saldo_cliente vs on vs.cliente_id = c.id
     where c.pos_cliente_id = any (p_cliente_ids);
end;
$function$
CREATE OR REPLACE FUNCTION hermes.revisar_documento(p_documento_id bigint, p_aprobado boolean, p_usuario text, p_notas text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
begin
  -- T0-4: antes exigía 'gerente' estricto. Ahora admin también, y
  -- contexto_confiable() para el editor SQL / service_role, igual que
  -- anular_partida y partir_partida.
  if not contexto_confiable() and rol_actual() not in ('gerente', 'admin') then
    raise exception 'Tu rol (%) no puede revisar documentos: hace falta gerente o admin',
                    coalesce(nullif(rol_actual(), ''), 'sin rol');
  end if;

  update documento
     set estado       = case when p_aprobado then 'APROBADO' else 'RECHAZADO' end::estado_documento,
         revisado_por = p_usuario,
         revisado_en  = now(),
         notas        = p_notas
   where id = p_documento_id
     and estado = 'SUBIDO';

  if not found then
    raise exception 'Documento % no existe o no está en estado SUBIDO', p_documento_id;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.calcular_imputacion_fifo(p_cliente_id bigint, p_monto numeric)
 RETURNS TABLE(o_partida_id bigint, o_referencia text, o_total numeric, o_pendiente numeric, o_aplica numeric, o_restante numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_disponible numeric := p_monto;
  v_p          record;
begin
  if p_monto is null or p_monto <= 0 then
    raise exception 'El monto a imputar debe ser mayor que cero';
  end if;

  for v_p in
    select ve.partida_id, ve.referencia, ve.total, ve.pendiente
      from v_partida_estado ve
     where ve.cliente_id = p_cliente_id
       and ve.estado = 'ABIERTA'
       and ve.pendiente > 0
     order by ve.creado_en, ve.partida_id      -- FIFO: la más vieja primero
  loop
    exit when v_disponible <= 0;

    o_partida_id := v_p.partida_id;
    o_referencia := v_p.referencia;
    o_total      := v_p.total;
    o_pendiente  := v_p.pendiente;
    o_aplica     := least(v_disponible, v_p.pendiente);
    o_restante   := v_p.pendiente - o_aplica;

    v_disponible := v_disponible - o_aplica;
    return next;
  end loop;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.sincronizar_entrega_pedido(p_pedido_id bigint, p_fecha date, p_usuario text DEFAULT 'sync-despacho-automatico'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_partida_id bigint;
begin
  -- Un pedido puede tener, hoy, como mucho una partida ABIERTA (verificado:
  -- 0 casos con más de una). Se toma la más reciente igual, por las dudas.
  select id into v_partida_id
    from partida_abierta
   where pedido_id = p_pedido_id and estado = 'ABIERTA'
   order by creado_en desc
   limit 1;

  if v_partida_id is null then
    -- No es un error. Puede que el cliente todavía no esté importado, o que
    -- la partida no se haya abierto todavía. El cron reintenta en la
    -- próxima corrida — cuando la partida exista, esto se aplica solo.
    return jsonb_build_object('aplicado', false, 'motivo', 'sin_partida_abierta');
  end if;

  -- registrar_fechas_partida ya hace todo lo demás: valida que la fecha no
  -- sea futura, recalcula `documentado`, y NO pisa una fecha ya cargada
  -- (usa coalesce) — así que llamarla dos veces con la misma fecha es
  -- inofensivo, y llamarla después de que alguien ya la cargó a mano
  -- tampoco cambia nada.
  perform registrar_fechas_partida(v_partida_id, p_fecha, null, null, p_usuario);

  return jsonb_build_object('aplicado', true, 'partida_id', v_partida_id);
end;
$function$
CREATE OR REPLACE FUNCTION hermes.registrar_cargo_saldo(p_cliente_id bigint, p_monto numeric, p_venta_id text, p_usuario_pos text, p_motivo text DEFAULT NULL::text)
 RETURNS TABLE(movimiento_id bigint, saldo_resultante numeric, cubierto_por_saldo boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_id bigint; v_clave text; v_saldo numeric; v_cliente_interno bigint;
begin
  if p_monto <= 0 then raise exception 'El monto debe ser positivo (%)', p_monto; end if;

  select id into v_cliente_interno from cliente where pos_cliente_id = p_cliente_id;
  if v_cliente_interno is null then
    raise exception 'Cliente % del POS no tiene registro importado en Hermes', p_cliente_id;
  end if;

  v_clave := 'pos-venta-' || p_venta_id;

  insert into movimiento_cuenta
    (cliente_id, tipo, monto, idempotencia_clave, fecha_efectiva, referencia, motivo, creado_por)
  values
    (v_cliente_interno, 'CARGO', p_monto, v_clave, current_date,
     'Venta POS #' || p_venta_id, coalesce(p_motivo, 'Venta cubierta con saldo a favor'),
     'pos:' || coalesce(p_usuario_pos, 'sistema'))
  on conflict (idempotencia_clave) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from movimiento_cuenta where idempotencia_clave = v_clave;
  end if;

  select saldo_confirmado into v_saldo from v_saldo_cliente where cliente_id = v_cliente_interno;
  return query select v_id, v_saldo, coalesce(v_saldo, 0) <= 0;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.anular_partida(p_partida_id bigint, p_motivo text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pa       record;
  v_aplicado numeric;
begin
  if not contexto_confiable() and rol_actual() <> 'gerente' then
    raise exception 'Solo el rol gerente puede anular una partida';
  end if;
  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'El motivo es obligatorio';
  end if;

  select * into v_pa from partida_abierta where id = p_partida_id for update;
  if not found then raise exception 'La partida % no existe', p_partida_id; end if;
  if v_pa.estado <> 'ABIERTA' then
    raise exception 'La partida % está en estado % y no se puede anular', p_partida_id, v_pa.estado;
  end if;

  select coalesce(sum(pap.monto), 0) into v_aplicado
    from pago_aplicacion pap
    join pago pg on pg.id = pap.pago_id
   where pap.partida_id = p_partida_id
     and pg.estado in ('CONFIRMADO', 'ACREDITADO');
  if v_aplicado > 0 then
    raise exception 'La partida % tiene Bs % aplicados: no se puede anular', p_partida_id, v_aplicado;
  end if;

  update partida_abierta
     set estado = 'ANULADA', anulada_en = now(), anulada_por = p_usuario,
         motivo_anulacion = btrim(p_motivo)
   where id = p_partida_id;

  insert into movimiento_cuenta (
    cliente_id, partida_id, tipo, monto, idempotencia_clave,
    fecha_efectiva, referencia, motivo, creado_por
  ) values (
    v_pa.cliente_id, p_partida_id, 'NOTA_CREDITO', -v_pa.total,
    'anulacion-partida-' || p_partida_id, current_date,
    v_pa.documento_interno, 'Anulación: ' || btrim(p_motivo), p_usuario
  );
end;
$function$
CREATE OR REPLACE FUNCTION hermes.partir_partida(p_partida_id bigint, p_monto numeric, p_usuario text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pa       record;
  v_aplicado numeric;
  v_num      bigint;
  v_serie    text;
  v_doc      text;
  v_nueva    bigint;
begin
  if not contexto_confiable() and rol_actual() <> 'gerente' then
    raise exception 'Solo el rol gerente puede partir una partida';
  end if;

  select * into v_pa from partida_abierta where id = p_partida_id for update;
  if not found then raise exception 'La partida % no existe', p_partida_id; end if;
  if v_pa.estado <> 'ABIERTA' then
    raise exception 'La partida % está en estado % y no se puede partir', p_partida_id, v_pa.estado;
  end if;
  if p_monto is null or p_monto <= 0 or p_monto >= v_pa.total then
    raise exception 'El monto a separar debe ser mayor que 0 y menor que el total (%)', v_pa.total;
  end if;

  select coalesce(sum(pap.monto), 0) into v_aplicado
    from pago_aplicacion pap
    join pago pg on pg.id = pap.pago_id
   where pap.partida_id = p_partida_id
     and pg.estado in ('CONFIRMADO', 'ACREDITADO');
  if v_pa.total - p_monto < v_aplicado then
    raise exception 'No se puede: quedarían Bs % en la partida original con Bs % ya aplicados',
      v_pa.total - p_monto, v_aplicado;
  end if;

  select serie into v_serie from contador_documento where tipo = 'PARTIDA';
  v_num := siguiente_numero('PARTIDA');
  v_doc := 'PART-' || v_serie || '-' || lpad(v_num::text, 5, '0');

  insert into partida_abierta (
    cliente_id, cliente_nombre, cliente_nit, cliente_categoria,
    pedido_id, venta_id, documento_interno, total,
    inicio_computo, plazo_dias, referencia, creado_por
  ) values (
    v_pa.cliente_id, v_pa.cliente_nombre, v_pa.cliente_nit, v_pa.cliente_categoria,
    v_pa.pedido_id, v_pa.venta_id, v_doc, p_monto,
    v_pa.inicio_computo, v_pa.plazo_dias,
    coalesce(v_pa.referencia, '') || ' (parcial de ' || v_pa.documento_interno || ')',
    p_usuario
  )
  returning id into v_nueva;

  update partida_abierta set total = total - p_monto where id = p_partida_id;

  insert into movimiento_cuenta (cliente_id, partida_id, tipo, monto, idempotencia_clave,
                                 fecha_efectiva, referencia, motivo, creado_por)
  values (v_pa.cliente_id, p_partida_id, 'NOTA_CREDITO', -p_monto,
          'particion-origen-' || v_nueva, current_date, v_pa.documento_interno,
          'Traspaso a ' || v_doc, p_usuario);

  insert into movimiento_cuenta (cliente_id, partida_id, tipo, monto, idempotencia_clave,
                                 fecha_efectiva, referencia, motivo, creado_por)
  values (v_pa.cliente_id, v_nueva, 'CARGO', p_monto,
          'particion-destino-' || v_nueva, current_date, v_doc,
          'Traspaso desde ' || v_pa.documento_interno, p_usuario);

  return v_nueva;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.partir_partida_por_tanda(p_partida_id bigint, p_monto numeric, p_pedido_nuevo_id bigint, p_motivo text, p_usuario text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pa       record;
  v_aplicado numeric;
  v_num      bigint;
  v_serie    text;
  v_doc      text;
  v_nueva    bigint;
  v_entrega_num int;
  v_raiz_id  bigint;
begin
  select * into v_pa from partida_abierta where id = p_partida_id for update;
  if not found then raise exception 'La partida % no existe', p_partida_id; end if;
  if v_pa.estado <> 'ABIERTA' then
    raise exception 'La partida % está en estado % y no se puede partir', p_partida_id, v_pa.estado;
  end if;
  if p_monto is null or p_monto <= 0 or p_monto >= v_pa.total then
    raise exception 'El monto a separar debe ser mayor que 0 y menor que el total (%)', v_pa.total;
  end if;

  select coalesce(sum(pap.monto), 0) into v_aplicado
    from pago_aplicacion pap
    join pago pg on pg.id = pap.pago_id
   where pap.partida_id = p_partida_id
     and pg.estado in ('CONFIRMADO', 'ACREDITADO');
  if v_pa.total - p_monto < v_aplicado then
    raise exception 'No se puede: quedarían Bs % en la partida original con Bs % ya aplicados',
      v_pa.total - p_monto, v_aplicado;
  end if;

  v_raiz_id := coalesce(v_pa.partida_raiz_id, v_pa.id);
  v_entrega_num := coalesce(v_pa.entrega_numero, 1) + 1;

  select serie into v_serie from contador_documento where tipo = 'PARTIDA';
  v_num := siguiente_numero('PARTIDA');
  v_doc := 'PART-' || v_serie || '-' || lpad(v_num::text, 5, '0');

  insert into partida_abierta (
    cliente_id, cliente_nombre, cliente_nit, cliente_categoria,
    pedido_id, documento_interno, total,
    inicio_computo, plazo_dias, referencia, creado_por,
    solicitante_id, solicitante_nombre,
    parent_partida_id, partida_raiz_id, entrega_numero
  ) values (
    v_pa.cliente_id, v_pa.cliente_nombre, v_pa.cliente_nit, v_pa.cliente_categoria,
    p_pedido_nuevo_id, v_doc, p_monto,
    v_pa.inicio_computo, v_pa.plazo_dias,
    coalesce(p_motivo, coalesce(v_pa.referencia,'') || ' (faltante de ' || v_pa.documento_interno || ')'),
    p_usuario,
    v_pa.solicitante_id, v_pa.solicitante_nombre,
    v_pa.id, v_raiz_id, v_entrega_num
  )
  returning id into v_nueva;

  update partida_abierta set total = total - p_monto where id = p_partida_id;

  -- si la raíz nunca se había partido antes (partida_raiz_id propio en NULL),
  -- se completa a sí misma para que el filtro "hermanas" de CONCILIADOR la encuentre.
  update partida_abierta set partida_raiz_id = v_raiz_id
   where id = v_raiz_id and partida_raiz_id is null;

  insert into movimiento_cuenta (cliente_id, partida_id, tipo, monto, idempotencia_clave,
                                 fecha_efectiva, referencia, motivo, creado_por)
  values (v_pa.cliente_id, p_partida_id, 'NOTA_CREDITO', -p_monto,
          'tanda-origen-' || v_nueva, current_date, v_pa.documento_interno,
          'Traspaso a ' || v_doc || ' (faltante de tanda)', p_usuario);

  insert into movimiento_cuenta (cliente_id, partida_id, tipo, monto, idempotencia_clave,
                                 fecha_efectiva, referencia, motivo, creado_por)
  values (v_pa.cliente_id, v_nueva, 'CARGO', p_monto,
          'tanda-destino-' || v_nueva, current_date, v_doc,
          'Traspaso desde ' || v_pa.documento_interno || ' (faltante de tanda)', p_usuario);

  return jsonb_build_object(
    'partida_madre_id', p_partida_id,
    'partida_hija_id', v_nueva,
    'entrega_numero', v_entrega_num,
    'documento_interno', v_doc,
    'monto', p_monto
  );
end;
$function$
CREATE OR REPLACE FUNCTION hermes.abrir_partida(p_pedido_id bigint, p_usuario text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_ped        record;
  v_cli        record;
  v_num        bigint;
  v_doc        text;
  v_serie      text;
  v_partida_id bigint;
begin
  select * into v_ped from hermes.cation_pedido where id = p_pedido_id;
  if not found then
    raise exception 'El pedido % no existe en Cation', p_pedido_id;
  end if;
  if v_ped.cliente_id is null then
    raise exception 'El pedido % no tiene cliente asignado', p_pedido_id;
  end if;
  if v_ped.total is null or v_ped.total <= 0 then
    raise exception 'El pedido % no tiene total (partida_abierta exige total > 0)', p_pedido_id;
  end if;

  select c.id, c.nombre, c.nit, c.categoria, cc.plazo_dias, cc.inicio_computo
    into v_cli
    from cliente c
    left join cliente_credito cc on cc.cliente_id = c.id
   where c.pos_cliente_id = v_ped.cliente_id;
  if not found then
    raise exception 'El cliente % del POS no tiene cuenta en Hermes — importalo primero', v_ped.cliente_id;
  end if;
  if v_cli.plazo_dias is null then
    raise exception 'El cliente % no tiene ficha de crédito', v_cli.nombre;
  end if;

  if v_cli.categoria not in ('INSTITUCIONAL', 'CORPORATIVO', 'MAYORISTA') then
    raise exception 'La categoría % no abre partida', v_cli.categoria;
  end if;

  select serie into v_serie from contador_documento where tipo = 'PARTIDA';
  v_num := siguiente_numero('PARTIDA');
  v_doc := 'PART-' || v_serie || '-' || lpad(v_num::text, 5, '0');

  insert into partida_abierta (
    cliente_id, cliente_nombre, cliente_nit, cliente_categoria,
    pedido_id, documento_interno, total,
    inicio_computo, plazo_dias, referencia, creado_por,
    solicitante_id, solicitante_nombre
  ) values (
    v_cli.id, v_cli.nombre, v_cli.nit, v_cli.categoria,
    v_ped.id, v_doc, v_ped.total,
    v_cli.inicio_computo, v_cli.plazo_dias,
    coalesce(nullif(btrim(coalesce(v_ped.numero, '')), ''),
             'Pedido POS #' || v_ped.id),
    p_usuario,
    v_ped.solicitante_id, v_ped.solicitado_por
  )
  returning id into v_partida_id;

  insert into movimiento_cuenta (
    cliente_id, partida_id, tipo, monto, idempotencia_clave,
    fecha_efectiva, referencia, motivo, creado_por
  ) values (
    v_cli.id, v_partida_id, 'CARGO', v_ped.total, 'partida-' || v_partida_id,
    current_date, v_doc, 'Apertura de partida', p_usuario
  );

  return v_partida_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.ingesta_dirigida(p_documento_id bigint, p_storage_path text, p_agente hermes.origen_documento, p_extraccion jsonb DEFAULT NULL::jsonb, p_confianza numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
begin
  if not contexto_confiable() and rol_actual() = '' then
    raise exception 'Requiere sesión autenticada o contexto de servicio';
  end if;
  if p_agente = 'HUMANO' then
    raise exception 'ingesta_dirigida es para agentes; un humano usa subir_documento';
  end if;
  if p_confianza is not null and (p_confianza < 0 or p_confianza > 1) then
    raise exception 'La confianza debe estar entre 0 y 1';
  end if;

  perform subir_documento(p_documento_id, p_storage_path, lower(p_agente::text));

  update documento
     set origen     = p_agente,
         confianza  = p_confianza,
         extraccion = p_extraccion
   where id = p_documento_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.ingesta_ciega(p_agente hermes.origen_documento, p_storage_path text, p_idempotencia_clave text, p_extraccion jsonb DEFAULT NULL::jsonb, p_confianza numeric DEFAULT NULL::numeric, p_partida_sugerida_id bigint DEFAULT NULL::bigint, p_documento_sugerido_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_id       bigint;
  v_existente bigint;
begin
  if not contexto_confiable() and rol_actual() = '' then
    raise exception 'Requiere sesión autenticada o contexto de servicio';
  end if;
  if p_idempotencia_clave is null or btrim(p_idempotencia_clave) = '' then
    raise exception 'La clave de idempotencia es obligatoria';
  end if;
  if p_agente = 'HUMANO' then
    raise exception 'ingesta_ciega es para agentes';
  end if;

  -- Reintento: devolver el id existente en vez de reventar. Un agente que
  -- perdió la respuesta por timeout tiene que poder repreguntar.
  select id into v_existente from bandeja_ingesta
   where idempotencia_clave = btrim(p_idempotencia_clave);
  if found then return v_existente; end if;

  insert into bandeja_ingesta (
    agente, storage_path, idempotencia_clave, extraccion, confianza,
    partida_sugerida_id, documento_sugerido_id
  ) values (
    p_agente, p_storage_path, btrim(p_idempotencia_clave), p_extraccion, p_confianza,
    p_partida_sugerida_id, p_documento_sugerido_id
  )
  returning id into v_id;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.proponer_pago(p_cliente_id_pos bigint, p_monto numeric, p_medio hermes.medio_pago, p_pedido_id_pos bigint DEFAULT NULL::bigint, p_movimiento_caja_id bigint DEFAULT NULL::bigint, p_usuario_pos text DEFAULT NULL::text, p_referencia text DEFAULT NULL::text)
 RETURNS TABLE(pago_id bigint, saldo_provisional numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_cliente_interno bigint; v_partida_id bigint; v_pago_id bigint; v_clave text; v_saldo numeric;
begin
  if p_monto <= 0 then raise exception 'El monto debe ser positivo (%)', p_monto; end if;

  select id into v_cliente_interno from cliente where pos_cliente_id = p_cliente_id_pos;
  if v_cliente_interno is null then
    raise exception 'Cliente % del POS no tiene registro importado en Hermes', p_cliente_id_pos;
  end if;

  v_clave := coalesce('pos-pago-mov-' || p_movimiento_caja_id, 'pos-pago-' || gen_random_uuid());

  insert into pago (cliente_id, medio, monto, estado, fecha_recepcion, referencia, idempotencia_clave, creado_por)
  values (v_cliente_interno, p_medio, p_monto, 'PROPUESTO', current_date,
          coalesce(p_referencia, 'Pago POS' || coalesce(' pedido #' || p_pedido_id_pos, '')),
          v_clave, 'pos:' || coalesce(p_usuario_pos, 'sistema'))
  on conflict (idempotencia_clave) do nothing
  returning id into v_pago_id;

  if v_pago_id is null then
    select id into v_pago_id from pago where idempotencia_clave = v_clave;
  else
    if p_pedido_id_pos is not null then
      select id into v_partida_id from partida_abierta where pedido_id = p_pedido_id_pos limit 1;
      if v_partida_id is not null then
        insert into pago_aplicacion (pago_id, partida_id, monto) values (v_pago_id, v_partida_id, p_monto);
      end if;
    end if;
  end if;

  select vs.saldo_provisional into v_saldo from v_saldo_cliente vs where vs.cliente_id = v_cliente_interno;
  return query select v_pago_id, v_saldo;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.actualizar_credito_cliente(p_cliente_id bigint, p_sector hermes.sector_cliente, p_limite_credito numeric, p_plazo_dias integer, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_actor          text;
  v_rol            text;
  v_limite_previo  numeric;
  v_plazo_previo   integer;
  v_limite_cambio  boolean;
  v_plazo_cambio   boolean;
begin
  v_actor := coalesce(auth.jwt() ->> 'email', current_user);
  v_rol   := rol_actual();   -- FIX: antes leía user_metadata directo

  select limite_credito, plazo_dias into v_limite_previo, v_plazo_previo
  from cliente_credito where cliente_id = p_cliente_id
  for update;

  if not found then
    raise exception 'Cliente % no tiene registro de crédito', p_cliente_id;
  end if;

  v_limite_cambio := v_limite_previo is distinct from p_limite_credito;
  v_plazo_cambio  := v_plazo_previo is distinct from p_plazo_dias;

  if v_limite_cambio or v_plazo_cambio then
    if v_rol <> 'gerente' then
      raise exception 'Solo el rol gerente puede modificar límite de crédito o plazo '
                      '(rol actual: %)', coalesce(nullif(v_rol,''), 'sin rol');
    end if;
    if coalesce(trim(p_motivo), '') = '' then
      raise exception 'El cambio de límite de crédito o plazo requiere un motivo';
    end if;
  end if;

  update cliente_credito
  set sector          = p_sector,
      limite_credito  = p_limite_credito,
      plazo_dias      = p_plazo_dias,
      actualizado_en  = now(),
      actualizado_por = v_actor
  where cliente_id = p_cliente_id;

  if v_limite_cambio then
    insert into cliente_credito_evento
      (cliente_id, campo, valor_previo, valor_nuevo, motivo, creado_por)
    values
      (p_cliente_id, 'limite_credito', v_limite_previo::text, p_limite_credito::text, p_motivo, v_actor);
  end if;

  if v_plazo_cambio then
    insert into cliente_credito_evento
      (cliente_id, campo, valor_previo, valor_nuevo, motivo, creado_por)
    values
      (p_cliente_id, 'plazo_dias', v_plazo_previo::text, p_plazo_dias::text, p_motivo, v_actor);
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.registrar_nota_credito(p_cliente_id bigint, p_monto numeric, p_motivo text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_actor text; v_rol text; v_id bigint;
begin
  v_actor := coalesce(auth.jwt() ->> 'email', current_user);
  v_rol   := hermes.rol_actual();

  if v_rol <> 'admin' then
    raise exception 'Solo el rol admin puede registrar notas de crédito (rol actual: %)',
                    coalesce(nullif(v_rol,''), 'sin rol');
  end if;

  if p_monto <= 0 then
    raise exception 'El monto debe ser positivo (%) -- se registra en contra del cliente automáticamente', p_monto;
  end if;

  if p_motivo is null or btrim(p_motivo) = '' then
    raise exception 'La nota de crédito requiere un motivo';
  end if;

  insert into movimiento_cuenta (cliente_id, tipo, monto, idempotencia_clave, fecha_efectiva, motivo, creado_por)
  values (p_cliente_id, 'NOTA_CREDITO', -p_monto, 'nota-credito-' || gen_random_uuid(),
          (now() at time zone 'America/La_Paz')::date, p_motivo, v_actor)
  returning id into v_id;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.confirmar_pago(p_pago_id bigint, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pago      record;
  v_rol       text;
  v_actor     text;
  v_n         int;
  v_a         record;
  v_imputado  numeric := 0;
  v_excedente numeric;
  v_fecha     date;
begin
  v_rol := hermes.rol_actual();
  if v_rol not in ('gerente','admin') then
    raise exception 'Solo el rol gerente puede confirmar pagos (rol actual: %)',
                    coalesce(nullif(v_rol,''), 'sin rol');
  end if;
  v_actor := coalesce(auth.jwt() ->> 'email', current_user);
  v_fecha := (now() at time zone 'America/La_Paz')::date;

  select * into v_pago from pago where id = p_pago_id for update;
  if not found then raise exception 'Pago % no existe', p_pago_id; end if;
  if v_pago.estado <> 'PROPUESTO' then
    raise exception 'El pago % está en estado % y no se puede confirmar', p_pago_id, v_pago.estado;
  end if;

  -- FIFO automático SOLO si el vendedor no lo marcó como anticipo.
  select count(*) into v_n from pago_aplicacion where pago_id = p_pago_id;
  if v_n = 0 and not v_pago.no_imputar then
    insert into pago_aplicacion (pago_id, partida_id, monto)
    select p_pago_id, f.o_partida_id, f.o_aplica
      from calcular_imputacion_fifo(v_pago.cliente_id, v_pago.monto) f;
  end if;

  update pago set estado = 'CONFIRMADO', confirmado_por = v_actor, confirmado_en = now()
   where id = p_pago_id;

  for v_a in
    select ap.partida_id, ap.monto, pa.documento_interno
      from pago_aplicacion ap
      join partida_abierta pa on pa.id = ap.partida_id
     where ap.pago_id = p_pago_id
     order by ap.partida_id
  loop
    insert into movimiento_cuenta (cliente_id, partida_id, pago_id, tipo, monto,
                                   idempotencia_clave, fecha_efectiva, referencia,
                                   motivo, creado_por)
    values (v_pago.cliente_id, v_a.partida_id, p_pago_id, 'PAGO', -v_a.monto,
            'pago-confirmado-' || p_pago_id || '-' || v_a.partida_id,
            v_fecha, coalesce(v_pago.referencia, v_a.documento_interno),
            'Pago confirmado', v_actor);
    v_imputado := v_imputado + v_a.monto;
  end loop;

  v_excedente := v_pago.monto - v_imputado;
  if v_excedente > 0 then
    insert into movimiento_cuenta (cliente_id, partida_id, pago_id, tipo, monto,
                                   idempotencia_clave, fecha_efectiva, referencia,
                                   motivo, creado_por)
    values (v_pago.cliente_id, null, p_pago_id, 'ANTICIPO', -v_excedente,
            'pago-anticipo-' || p_pago_id, v_fecha, v_pago.referencia,
            case when v_pago.no_imputar then 'Anticipo a favor del cliente'
                 else 'Excedente sin imputar' end,
            v_actor);
  end if;

  update partida_abierta pa
     set estado = 'PAGADA'
    from v_partida_estado ve
   where ve.partida_id = pa.id
     and pa.id in (select ap.partida_id from pago_aplicacion ap where ap.pago_id = p_pago_id)
     and pa.estado = 'ABIERTA'
     and ve.pendiente <= 0;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.importar_clientes_cation()
 RETURNS TABLE(cliente_id bigint, nombre text, categoria hermes.categoria_cliente, documento_junk boolean, nombre_sospecha boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  r record;
  v_categoria categoria_cliente;
  v_inicio    inicio_computo;
  v_sector    sector_cliente;
begin
  for r in
    select cp.id, btrim(cp.nombre) as nombre, cp.documento, cp.tipo_precio
      from hermes.cation_cliente cp
     where cp.activo
       and lower(btrim(coalesce(cp.tipo_precio, ''))) <> 'retail'
       and not exists (select 1 from cliente c where c.pos_cliente_id = cp.id)
     order by cp.id
  loop
    v_categoria := categoria_desde_tipo_precio(r.tipo_precio);

    if v_categoria is null then
      -- tipo_precio no mapea a ninguna categoría conocida: se salta y se
      -- reporta como NULL en categoria para que quede visible en la salida,
      -- en vez de fallar toda la corrida por un solo registro raro.
      cliente_id := r.id;
      nombre := r.nombre;
      categoria := null;
      documento_junk := null;
      nombre_sospecha := null;
      return next;
      continue;
    end if;

    v_inicio := case v_categoria
                  when 'INSTITUCIONAL' then 'FACTURA'::inicio_computo
                  else 'ENTREGA'::inicio_computo
                end;
    v_sector := case v_categoria
                  when 'INSTITUCIONAL' then 'PUBLICO'::sector_cliente
                  else 'PRIVADO'::sector_cliente
                end;

    insert into cliente (id, nombre, nit, categoria, activo, sincronizado_en, importado_en, pos_cliente_id)
    values (r.id, r.nombre, r.documento, v_categoria, true, now(), now(), r.id)
    on conflict (pos_cliente_id) do nothing;

    -- Si el ON CONFLICT saltó la inserción (carrera con otra corrida), no se
    -- crea la ficha de crédito duplicada tampoco.
    if found then
      insert into cliente_credito (cliente_id, sector, inicio_computo, plazo_dias, actualizado_por)
      values (r.id, v_sector, v_inicio, 30, 'importar_clientes_cation');
    end if;

    cliente_id      := r.id;
    nombre          := r.nombre;
    categoria       := v_categoria;
    documento_junk  := (r.documento is null or r.documento ~ '^[-\.\s0]*$');
    nombre_sospecha := (r.nombre ilike '%prueba%' or r.nombre ilike '%generico%' or r.nombre ilike '%test%');
    return next;
  end loop;

  return;
end;
$function$
CREATE OR REPLACE FUNCTION public.comision_trigger_sync_partida_pedido()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'hermes', 'pg_temp'
AS $function$
begin
  if new.estado = 'COMPLETADO' and (TG_OP = 'INSERT' or old.estado is distinct from new.estado) then
    begin
      perform hermes.sincronizar_pedidos_cation();
    exception when others then
      -- Nunca abortar el cierre de un pedido por un fallo de sincronización de cartera.
      raise warning 'sincronizar_pedidos_cation() tras pedido % falló: % (%)', new.id, sqlerrm, sqlstate;
    end;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.registrar_anticipo(p_pedido_id bigint DEFAULT NULL::bigint, p_cliente_id bigint DEFAULT NULL::bigint, p_monto numeric DEFAULT NULL::numeric, p_metodo metodo_pago DEFAULT NULL::metodo_pago, p_sesion_id bigint DEFAULT NULL::bigint, p_usuario text DEFAULT NULL::text, p_idempotencia text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
declare
  v_id bigint; v_cliente_id bigint; v_existe boolean; v_existente bigint;
begin
  -- Cortocircuito de reintento: va antes de cualquier validación. Un reintento
  -- con la misma clave devuelve el movimiento que ya existe, sin insertar de
  -- nuevo y sin error — para el frontend es indistinguible de un éxito directo.
  if p_idempotencia is not null then
    select id into v_existente
    from movimiento_caja
    where idempotencia_clave = p_idempotencia;

    if found then
      return v_existente;
    end if;
  end if;

  if p_monto is null or p_monto <= 0 then raise exception 'Monto inválido'; end if;
  if p_pedido_id is null and p_cliente_id is null then
    raise exception 'Hace falta un pedido o un cliente';
  end if;

  if p_pedido_id is not null then
    select true, cliente_id into v_existe, v_cliente_id from pedido where id = p_pedido_id;
    if not v_existe then raise exception 'Pedido % no existe', p_pedido_id; end if;
    if v_cliente_id is null then raise exception 'El pedido % no tiene cliente asignado', p_pedido_id; end if;
  else
    perform 1 from cliente where id = p_cliente_id;
    if not found then raise exception 'Cliente % no existe', p_cliente_id; end if;
    v_cliente_id := p_cliente_id;
  end if;

  perform 1 from sesion_caja where id = p_sesion_id and estado = 'ABIERTA';
  if not found then raise exception 'La sesión % no está abierta', p_sesion_id; end if;

  insert into movimiento_caja (sesion_caja_id, tipo, metodo, monto, pedido_id, cliente_id, creado_por, nota, idempotencia_clave)
  values (p_sesion_id, 'ANTICIPO', p_metodo, p_monto, p_pedido_id,
          case when p_pedido_id is null then v_cliente_id else null end,
          p_usuario,
          case when p_pedido_id is not null then 'Anticipo pedido #' || p_pedido_id
               else 'Pago sobre saldo total' end,
          p_idempotencia)
  returning id into v_id;

  return v_id;

-- Carrera entre dos requests simultáneos con la misma clave: el índice único
-- parcial hace que el segundo insert falle con 23505 en vez de duplicar.
-- Se relee y se devuelve el que ganó, en vez de propagar el error.
exception when unique_violation then
  if p_idempotencia is not null then
    select id into v_existente from movimiento_caja where idempotencia_clave = p_idempotencia;
    if found then return v_existente; end if;
  end if;
  raise;
end;
$function$
