CREATE OR REPLACE FUNCTION hermes.sincronizar_pedidos_cation()
 RETURNS TABLE(abiertas integer, omitidas integer, con_error integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  r          record;
  v_abiertas int := 0;
  v_error    int := 0;
  v_omitidas int;
begin
  -- Se toma ANTES del loop a propósito: después, los pedidos recién abiertos
  -- ya figuran como YA_TIENE_PARTIDA y se contarían dos veces.
  select count(*)::int into v_omitidas from v_pedidos_cation_pendientes where motivo <> 'ABRE';

  for r in select pedido_id from v_pedidos_cation_pendientes where motivo = 'ABRE' order by pedido_id
  loop
    begin
      perform abrir_partida(r.pedido_id, 'sync-cation');
      v_abiertas := v_abiertas + 1;
    exception when others then
      v_error := v_error + 1;
      raise warning 'Pedido %: %', r.pedido_id, sqlerrm;
    end;
  end loop;

  return query select v_abiertas, v_omitidas, v_error;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.rol_actual()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
  -- 2026-09-13: unificación de bases. Antes leía app_metadata del JWT; ahora
  -- lee perfil, igual que app_rol_actual() de Cation.
  -- El filtro por hermes_acceso es lo que impide que un admin del POS sin
  -- autorización al Conciliador pase los chequeos internos de las funciones
  -- SECURITY DEFINER, que no ven RLS.
  select coalesce((select p.rol from public.perfil p
                    where p.id = auth.uid()
                      and p.activo
                      and p.hermes_acceso
                    limit 1), '');
$function$
CREATE OR REPLACE FUNCTION hermes.evaluar_credito(p_cliente_id bigint, p_monto numeric)
 RETURNS TABLE(permitido boolean, saldo_confirmado numeric, saldo_provisional numeric, limite_credito numeric, vencidos_documentados numeric, vencidos_sin_documentar numeric, sin_fecha_de_inicio numeric, contado_sin_cobrar numeric, entregados_sin_facturar integer, cheques_en_cartera numeric, motivo_advertencia text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_saldo   numeric := 0;
  v_prov    numeric := 0;
  v_limite  numeric;
  v_vd      numeric := 0;
  v_vs      numeric := 0;
  v_sfi     numeric := 0;
  v_csc     numeric := 0;
  v_csc_fecha_min date;      -- FIX: antes esto era `v_csc_dias integer`
  v_csc_dias integer;        -- se calcula recién después, a partir de la fecha
  v_esf     integer := 0;
  v_chq     numeric := 0;
  v_motivos text[] := '{}';
begin
  select s.saldo_confirmado, s.saldo_provisional, s.limite_credito
    into v_saldo, v_prov, v_limite
    from v_saldo_cliente s
   where s.cliente_id = p_cliente_id;

  select
    coalesce(sum(a.saldo_partida) filter (
      where a.inicio_computo <> 'CONTADO'
        and a.fecha_vencimiento < current_date and a.documentado), 0),
    coalesce(sum(a.saldo_partida) filter (
      where a.inicio_computo <> 'CONTADO'
        and a.fecha_vencimiento < current_date and not a.documentado), 0),
    coalesce(sum(a.saldo_partida) filter (
      where a.estado_reloj = 'RELOJ_SIN_ARRANCAR'), 0),
    coalesce(sum(a.saldo_partida) filter (
      where a.inicio_computo = 'CONTADO' and a.fecha_vencimiento < current_date), 0),
    count(*) filter (where a.dias_entregado_sin_facturar is not null)
  into v_vd, v_vs, v_sfi, v_csc, v_esf
  from v_antiguedad a
  where a.cliente_id = p_cliente_id;

  select coalesce(sum(monto), 0) into v_chq
    from v_cheques_en_cartera
   where cliente_id = p_cliente_id;

  -- FIX: la fecha va a su propia variable `date`, no a v_csc_dias.
  select min(a.fecha_vencimiento) into v_csc_fecha_min
    from v_antiguedad a
   where a.cliente_id = p_cliente_id
     and a.inicio_computo = 'CONTADO' and a.fecha_vencimiento < current_date;

  if v_csc_fecha_min is not null then
    v_csc_dias := current_date - v_csc_fecha_min;
  end if;

  if v_limite is not null and (coalesce(v_saldo, 0) + p_monto) > v_limite then
    v_motivos := v_motivos || format('Excede el límite de crédito en %s Bs',
      to_char(coalesce(v_saldo, 0) + p_monto - v_limite, 'FM999G999G990D00'));
  end if;

  if v_vs > 0 then
    v_motivos := v_motivos || format(
      'Tiene %s Bs vencidos SIN documentar (falta acta firmada)',
      to_char(v_vs, 'FM999G999G990D00'));
  end if;

  if v_vd > 0 then
    v_motivos := v_motivos || format(
      'Tiene %s Bs vencidos (ya documentados)',
      to_char(v_vd, 'FM999G999G990D00'));
  end if;

  if v_csc > 0 then
    v_motivos := v_motivos || format(
      'Tiene %s Bs en ventas al contado sin cobrar (la más antigua, de hace %s día%s)',
      to_char(v_csc, 'FM999G999G990D00'), coalesce(v_csc_dias, 0),
      case when coalesce(v_csc_dias, 0) = 1 then '' else 's' end);
  end if;

  if v_chq > 0 then
    v_motivos := v_motivos || format(
      'Tiene %s Bs en cheques recibidos y no acreditados',
      to_char(v_chq, 'FM999G999G990D00'));
  end if;

  if v_esf > 0 then
    v_motivos := v_motivos ||
      format('%s pedido(s) entregado(s) sin facturar', v_esf);
  end if;

  if v_sfi > 0 then
    v_motivos := v_motivos || format(
      'Tiene %s Bs sin fecha de entrega o factura registrada: el plazo todavía no empezó a correr (pendiente interno)',
      to_char(v_sfi, 'FM999G999G990D00'));
  end if;

  return query select
    cardinality(v_motivos) = 0,
    coalesce(v_saldo, 0), coalesce(v_prov, 0), v_limite,
    v_vd, v_vs, v_sfi, v_csc, v_esf, v_chq,
    nullif(array_to_string(v_motivos, ' · '), '');
end;
$function$
CREATE OR REPLACE FUNCTION hermes.procesar_adicion_pedido(p_pedido_id bigint, p_monto_adicional numeric, p_motivo text DEFAULT NULL::text, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_actual         partida_abierta%rowtype;
  v_nueva_id       bigint;
  v_doc            text;
  v_entrega_num    integer;
  v_camino         text;
  v_habilitantes_reabiertos int := 0;
begin
  if not contexto_confiable() and rol_actual() not in ('gerente', 'admin') then
    raise exception 'Tu rol (%) no puede procesar adiciones de pedido: hace falta gerente o admin',
                    coalesce(nullif(rol_actual(), ''), 'sin rol');
  end if;

  if p_monto_adicional is null or p_monto_adicional <= 0 then
    raise exception 'monto_adicional debe ser positivo';
  end if;

  select * into v_actual
    from partida_abierta
   where pedido_id = p_pedido_id and estado = 'ABIERTA'
   order by entrega_numero desc
   limit 1;

  if v_actual.id is null then
    raise exception 'El pedido % no tiene ninguna partida abierta en Hermes — abrila primero con abrir_partida', p_pedido_id;
  end if;

  if v_actual.fecha_entrega is null then
    v_camino := 'MISMA_PARTIDA';

    update partida_abierta
       set total = total + p_monto_adicional
     where id = v_actual.id;

    insert into movimiento_cuenta (
      cliente_id, partida_id, tipo, monto, idempotencia_clave,
      fecha_efectiva, referencia, motivo, creado_por
    ) values (
      v_actual.cliente_id, v_actual.id, 'CARGO', p_monto_adicional,
      'adicion-' || v_actual.id || '-' || extract(epoch from now())::bigint,
      current_date, v_actual.documento_interno,
      coalesce(p_motivo, 'Ítems agregados al pedido'), p_usuario
    );

    with reabiertos as (
      update documento d
         set estado       = 'PENDIENTE',
             revisado_por = null,
             revisado_en  = null,
             notas        = coalesce(d.notas || ' · ', '') || '[Reabierto automáticamente: el monto de la partida cambió]'
        from hito h
        join hito_plantilla hp on hp.id = h.hito_plantilla_id
       where d.hito_id = h.id
         and h.partida_abierta_id = v_actual.id
         and hp.fase = 'PREVIA'
         and d.tipo = 'HABILITANTE'
         and d.estado = 'APROBADO'
      returning d.id
    )
    select count(*) into v_habilitantes_reabiertos from reabiertos;

    update hito h
       set estado = 'PENDIENTE', completado_en = null, completado_por = null
      from hito_plantilla hp
     where h.hito_plantilla_id = hp.id
       and h.partida_abierta_id = v_actual.id
       and hp.fase = 'PREVIA'
       and h.estado = 'COMPLETO'
       and exists (
         select 1 from documento d where d.hito_id = h.id and d.estado = 'PENDIENTE'
       );

    v_nueva_id := v_actual.id;

  else
    v_camino := 'PARTIDA_HIJA';
    v_entrega_num := v_actual.entrega_numero + 1;

    select documento_interno into v_doc from partida_abierta where id = v_actual.partida_raiz_id;
    v_doc := v_doc || ' · Entrega ' || v_entrega_num;

    insert into partida_abierta (
      cliente_id, cliente_nombre, cliente_nit, cliente_categoria,
      pedido_id, documento_interno, total,
      inicio_computo, plazo_dias, referencia, creado_por,
      solicitante_id, solicitante_nombre,
      parent_partida_id, partida_raiz_id, entrega_numero
    ) values (
      v_actual.cliente_id, v_actual.cliente_nombre, v_actual.cliente_nit, v_actual.cliente_categoria,
      p_pedido_id, v_doc, p_monto_adicional,
      v_actual.inicio_computo, v_actual.plazo_dias, v_actual.referencia, p_usuario,
      v_actual.solicitante_id, v_actual.solicitante_nombre,
      v_actual.id, v_actual.partida_raiz_id, v_entrega_num
    )
    returning id into v_nueva_id;

    insert into movimiento_cuenta (
      cliente_id, partida_id, tipo, monto, idempotencia_clave,
      fecha_efectiva, referencia, motivo, creado_por
    ) values (
      v_actual.cliente_id, v_nueva_id, 'CARGO', p_monto_adicional,
      'apertura-' || v_nueva_id,
      current_date, v_doc,
      coalesce(p_motivo, 'Nueva entrega del pedido'), p_usuario
    );
  end if;

  return jsonb_build_object(
    'camino', v_camino,
    'partida_id', v_nueva_id,
    'entrega_numero', coalesce(v_entrega_num, v_actual.entrega_numero),
    'documento_interno', coalesce(v_doc, v_actual.documento_interno),
    'habilitantes_reabiertos', v_habilitantes_reabiertos
  );
end;
$function$
CREATE OR REPLACE FUNCTION hermes.completar_hito(p_hito_id bigint, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pendientes int;
begin
  -- T0-4: mismo criterio que revisar_documento.
  if not contexto_confiable() and rol_actual() not in ('gerente', 'admin') then
    raise exception 'Tu rol (%) no puede completar hitos: hace falta gerente o admin',
                    coalesce(nullif(rol_actual(), ''), 'sin rol');
  end if;

  select count(*) into v_pendientes
    from documento
   where hito_id = p_hito_id
     and tipo = 'HABILITANTE'
     and estado <> 'APROBADO';

  if v_pendientes > 0 then
    raise exception 'El hito % todavía tiene % documento(s) habilitante(s) sin aprobar',
                    p_hito_id, v_pendientes;
  end if;

  update hito
     set estado         = 'COMPLETO',
         completado_en  = now(),
         completado_por = p_usuario
   where id = p_hito_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.registrar_fechas_partida(p_partida_id bigint, p_fecha_entrega date, p_fecha_factura date, p_cuf text, p_usuario text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pa record;
  v_habilitantes_pendientes int;
begin
  if not contexto_confiable()
     and rol_actual() not in ('gerente', 'admin', 'supervisor', 'comercial') then
    raise exception 'Tu rol no puede registrar fechas de la partida';
  end if;

  select * into v_pa from partida_abierta where id = p_partida_id for update;
  if not found then raise exception 'La partida % no existe', p_partida_id; end if;
  if v_pa.estado <> 'ABIERTA' then
    raise exception 'La partida % está en estado %', p_partida_id, v_pa.estado;
  end if;

  if p_fecha_entrega is not null and p_fecha_entrega > current_date then
    raise exception 'La fecha de entrega no puede ser futura';
  end if;
  if p_fecha_factura is not null and p_fecha_factura > current_date then
    raise exception 'La fecha de factura no puede ser futura';
  end if;
  if p_fecha_factura is not null and coalesce(p_fecha_entrega, v_pa.fecha_entrega) is null then
    raise exception 'No se puede registrar la factura sin fecha de entrega';
  end if;
  if p_fecha_factura is not null
     and p_fecha_factura < coalesce(p_fecha_entrega, v_pa.fecha_entrega) then
    raise exception 'La factura no puede ser anterior a la entrega';
  end if;

  select count(*) into v_habilitantes_pendientes
    from documento d
    join hito h on h.id = d.hito_id
   where h.partida_abierta_id = p_partida_id
     and d.tipo = 'HABILITANTE'
     and d.estado <> 'APROBADO';

  update partida_abierta
     set fecha_entrega = coalesce(p_fecha_entrega, fecha_entrega),
         fecha_factura = coalesce(p_fecha_factura, fecha_factura),
         cuf           = coalesce(nullif(btrim(coalesce(p_cuf, '')), ''), cuf),
         documentado   = (v_habilitantes_pendientes = 0)
   where id = p_partida_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.imputar_pago(p_pago_id bigint, p_aplicaciones jsonb, p_usuario text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_pago      record;
  v_a         record;
  v_suma      numeric := 0;
  v_pendiente numeric;
  v_n         int := 0;
begin
  select * into v_pago from pago where id = p_pago_id for update;
  if not found then
    raise exception 'Pago % no existe', p_pago_id;
  end if;
  if v_pago.estado <> 'PROPUESTO' then
    raise exception 'El pago % está en estado % — solo se puede imputar un PROPUESTO',
      p_pago_id, v_pago.estado;
  end if;
  if v_pago.no_imputar and jsonb_array_length(coalesce(p_aplicaciones,'[]'::jsonb)) > 0 then
    raise exception 'El pago % está marcado como anticipo (no imputar). '
                    'Quitá esa marca antes de repartirlo entre partidas.', p_pago_id;
  end if;

  delete from pago_aplicacion where pago_id = p_pago_id;

  for v_a in
    select (x->>'partida_id')::bigint as partida_id,
           (x->>'monto')::numeric     as monto
      from jsonb_array_elements(coalesce(p_aplicaciones,'[]'::jsonb)) x
  loop
    if v_a.monto is null or v_a.monto <= 0 then
      raise exception 'Monto inválido (%) para la partida %', v_a.monto, v_a.partida_id;
    end if;

    select ve.pendiente into v_pendiente
      from v_partida_estado ve
     where ve.partida_id = v_a.partida_id and ve.cliente_id = v_pago.cliente_id;

    if v_pendiente is null then
      raise exception 'La partida % no existe o no pertenece al cliente del pago', v_a.partida_id;
    end if;
    if v_a.monto > v_pendiente then
      raise exception 'No se puede imputar % a la partida %: solo quedan pendientes %',
        v_a.monto, v_a.partida_id, v_pendiente;
    end if;

    insert into pago_aplicacion (pago_id, partida_id, monto)
    values (p_pago_id, v_a.partida_id, v_a.monto);

    v_suma := v_suma + v_a.monto;
    v_n := v_n + 1;
  end loop;

  if v_suma > v_pago.monto then
    raise exception 'La suma imputada (%) supera el monto del pago (%)', v_suma, v_pago.monto;
  end if;

  return jsonb_build_object(
    'pago_id', p_pago_id, 'aplicaciones', v_n,
    'imputado', v_suma, 'excedente', v_pago.monto - v_suma);
end;
$function$
