CREATE OR REPLACE FUNCTION hermes.resolver_documento(p_etapa text, p_referencia text)
 RETURNS TABLE(partida_id bigint, documento_interno text, cliente text, categoria hermes.categoria_cliente, pedido_id bigint, coincidencia text, hito_id bigint, hito text, documento_id bigint, etiqueta text, tipo hermes.tipo_documento, estado hermes.estado_documento)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_ref   text := btrim(coalesce(p_referencia, ''));
  v_etapa text := btrim(coalesce(p_etapa, ''));
begin
  if not contexto_confiable() and rol_actual() = '' then
    raise exception 'Requiere sesión autenticada o contexto de servicio';
  end if;
  if v_ref = '' then
    raise exception 'La referencia es obligatoria (número de pedido o nombre del cliente)';
  end if;
  if v_etapa = '' then
    raise exception 'La etapa es obligatoria';
  end if;

  return query
  with cand as (
    select pa.id                as partida_id,
           pa.documento_interno,
           pa.cliente_nombre    as cliente,
           pa.cliente_categoria as categoria,
           pa.pedido_id,
           case when pa.pedido_id::text = v_ref then 'PEDIDO' else 'CLIENTE' end as coincidencia
      from partida_abierta pa
     where pa.estado = 'ABIERTA'
       and ( pa.pedido_id::text = v_ref
          or pa.cliente_nombre ilike '%' || v_ref || '%'
          or pa.documento_interno ilike '%' || v_ref || '%' )
  ), hitos as (
    select c.*,
           h.id    as hito_id,
           h.nombre as hito,
           h.orden,
           rank() over (
             partition by c.partida_id
             order by case when lower(h.nombre) = lower(v_etapa) then 0 else 1 end
           ) as rk
      from cand c
      join hito h on h.partida_abierta_id = c.partida_id
     where h.nombre ilike v_etapa || '%'
  )
  select x.partida_id, x.documento_interno, x.cliente, x.categoria, x.pedido_id,
         x.coincidencia, x.hito_id, x.hito,
         d.id, d.etiqueta, d.tipo, d.estado
    from hitos x
    join documento d on d.hito_id = x.hito_id
                    and d.estado in ('PENDIENTE', 'RECHAZADO')
   where x.rk = 1
   order by (x.coincidencia = 'PEDIDO') desc, x.partida_id, x.orden, d.id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.cargar_saldo_apertura(p_cliente_id bigint, p_saldo numeric, p_motivo text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_corte date; v_actor text; v_rol text; v_id bigint;
begin
  v_actor := coalesce(auth.jwt() ->> 'email', current_user);
  v_rol   := hermes.rol_actual();

  if v_rol <> 'admin' then
    raise exception 'Solo el rol admin puede cargar saldos de apertura (rol actual: %)',
                    coalesce(nullif(v_rol,''), 'sin rol');
  end if;

  select valor::date into v_corte from parametro where clave = 'fecha_corte_apertura';

  insert into movimiento_cuenta
    (cliente_id, tipo, monto, idempotencia_clave, fecha_efectiva, motivo, creado_por)
  values
    (p_cliente_id, 'SALDO_APERTURA', p_saldo, 'apertura-' || p_cliente_id, v_corte, p_motivo, v_actor)
  returning id into v_id;

  return v_id;
end;
$function$
CREATE OR REPLACE FUNCTION hermes.obtener_detalle_pedido_cation(p_pedido_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'hermes', 'public'
AS $function$
declare
  v_cotizacion_id bigint;
  v_lineas jsonb;
  v_cotizacion jsonb;
begin
  if rol_actual() = '' then
    raise exception 'No autenticado';
  end if;

  select cotizacion_origen_id into v_cotizacion_id
    from hermes.cation_pedido where id = p_pedido_id;

  select coalesce(jsonb_agg(l order by l.id), '[]'::jsonb) into v_lineas
    from public.v_pedido_linea_hermes l where l.pedido_id = p_pedido_id;

  if v_cotizacion_id is not null then
    select to_jsonb(c) into v_cotizacion
      from public.v_cotizacion_hermes c where c.id = v_cotizacion_id;
  end if;

  return jsonb_build_object(
    'cotizacion_origen_id', v_cotizacion_id,
    'lineas', v_lineas,
    'cotizacion', v_cotizacion
  );
end;
